function die() {
  lives--;
  score = Math.max(0, score - 5); 

  if (lives <= 0) {
    gameState = 'GAMEOVER';
  } else {
    player.r = 0;
    player.c = 0;
    player.prevR = 0;
    player.prevC = 0;
    player.animProgress = 1.0;
    player.falling = false;
    enemies = [];
  }
}
